# English publication adaptation of a historical script; no experiment or adjudication was rerun.
"""Render the paper-facing report from the computed source tables, without changing labels."""
from pathlib import Path
import csv, json, hashlib, collections
P = Path(__file__).resolve().parent

def rows(n):
    with (P / n).open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))

def pct(v):
    return 'NA' if v in ['', None] else f'{100 * float(v):.2f}'

def num(v):
    return 'NA' if v in ['', None] else f'{float(v):,.2f}'

def label(cell):
    d, m, c, p, t = cell.split('|')
    model = 'DS' if m.startswith('DeepSeek') else 'Qwen'
    return f"{d} {model} {c} {p.split('@')[1]}" + (' star' if t == 'star_bidirectional' else '')

def table(headers, data):

    def esc(v):
        return str(v).replace('|', '\\|').replace('\n', ' ')
    return '\n'.join(['| ' + ' | '.join(headers) + ' |', '| ' + ' | '.join(['---'] * len(headers)) + ' |'] + ['| ' + ' | '.join((esc(v) for v in r)) + ' |' for r in data]) + '\n'
S = rows('condition_and_stratum_tables.csv')
D = rows('paired_condition_differences.csv')
G = rows('scope_global_metrics.csv')
C = rows('panel_cells.csv')
IDX = {(r['kind'], r['view'], r['cell_id'], r['phase'], r['question_stratum'], r['metric']): r for r in S}
GI = {(r['kind'], r['view'], r['metric']): r for r in G}

def val(kind, view, metric):
    return GI.get((kind, view, metric), {}).get('estimated_count', 0)

def stat(cell, metric, view='audit_HT', kind='node', phase='all', st='ALL'):
    return IDX[kind, view, cell, phase, st, metric]

def ci(r, field='question_macro_mean'):
    return f"{pct(r[field])} [{pct(r['bootstrap_lower'])}, {pct(r['bootstrap_upper'])}]"
maincells = [r for r in C if 'DeepSeek/' in r['cell_id'] and '@1.0.4|' in r['cell_id']]
auxcells = [r for r in C if r not in maincells]
parts = []
parts.append('# Node and edge statistics for the frozen exploratory substudy\n\nDate: 2026-10-13 (Asia/Shanghai). This report completes message-node and dependency-edge statistics for the frozen 60-question, 680-original-protocol-observation panel, including human-audit primary estimates, question/condition/stratum results, paired contrasts, descriptive intervals, candidate usability and sensitivity. **It is neither a terminal-union report nor the full original M3 confirmatory analysis.** The union rationale is in `UNION_DESIGN_ASSESSMENT.md`.\n\n## 1. Study scope and valid denominators\n\n2Wiki has 40 questions, ten in each of four types. MuSiQue has 20 questions with six question-stratum-by-hop cells containing 6, 4, 3, 1, 4 and 2 questions. DeepSeek averages r1/r2 within the same question, condition and protocol before equal-question aggregation; Qwen has r1 only for each topology. All observations use the original protocol, with no repair or matched supplemental observations.\n\nIdentity checks separate 520 DeepSeek 1.0.4 primary-comparison observations, 80 older-M observations, 40 Qwen-chain observations and 40 star_bidirectional observations. Older protocols and auxiliary topologies do not enter primary condition comparisons. The 680 observations are not 680 independent questions.\n')
parts.append(table(['Analysis cell', 'Questions', 'observation', 'node scope', 'edge scope'], [[label(r['cell_id']), r['question_n'], r['observation_n'], r['node_scope_n'], r['edge_scope_n'] if r['edge_scope_n'] != '0' else 'NA (no edges)'] for r in maincells + auxcells]))
parts.append("Original formal review covered 769 node and 559 edge records. From the remaining populations, 633 of 6,329 nodes were reviewed across 24 strata, and 189 of 1,885 edges across eight strata. Thus 1,402 nodes and 748 edges have itemwise review; the 5,696 unsampled nodes and 1,696 unsampled edges do not have itemwise human-final status. The 633 node items are human-review forms; this analysis generated M2-validated conversion records retaining `is_final=false`, not replacements for the formal adjudication registry.\n\nOriginal risk-directed review enters as exact evidence rather than proportionally extrapolated evidence. The remainder uses fixed N_h/n_h weights. The primary population estimate is original formal review plus weighted sample expansion over the remaining population. Sampled items are already represented in the latter and must not be counted again. Review includes author LRR review, evidence checking and sign-off, and cannot collectively be described as independent blind review.\n\n## 2. Metrics and statistical methods\n\nCSR denotes complete semantic equivalence; ESS requires complete equivalence plus exact equality to the canonical source set; VSSR denotes sufficiently supported valid source substitution; AA requires complete equivalence and current sources assessed as fully_supported. All four use the relevant message-node truth-scope denominator; disposition=decided is not a substitute. Five support outcomes are mutually exclusive under M2 and sum to the valid denominator.\n\n`review_status=decided` differs from `disposition=decided`. All reviewed analysis records have resolved review status. Absent is an observed failure to express the claim and counts as nonsurvival in the CSR denominator. Reviewed disposition=missing does not mean engineering failure or a missing judgment file. Nonequivalence can also be semantic_negative, so disposition cannot replace claim_presence. Engineering failures, missing judgments and needs_review are not automatically zeros.\n\nEdge ClaimRetention uses claim_event other than not_applicable as denominator. ExactSourceRetention uses retained/rewritten/split/merged, with its numerator restricted to the same event domain. ValidSubstitution uses valid/invalid substitution as denominator. Not_applicable is not an error. Multiple source_events can apply, so source-event distributions need not be mutually exclusive.\n\nPrimary in-scope tables use direct HT expansion. Each observation's estimated metric count is divided by its actual complete scope count, repetitions are averaged within question, and questions receive equal weight. Dataset aggregates weight strata by frozen question counts. Estimated group weights need not equal actual group scope counts; linear HT question, small-stratum or small-condition estimates can leave [0,1]. They are not question-level correctness probabilities and are not clipped. MuSiQue B0's 108.42% question-macro CSR illustrates this instability.\n\nCandidate-assisted difference correction is also reported: original exact review + candidate metrics for the entire remainder + Σw×(sample human metric − original candidate metric). It uses the complete candidate structure to reduce direct-expansion variation, retaining HT as primary and assigning no new labels to unsampled records. It was added after the first grouped results, with its rationale and edge-numerator applicability correction recorded in `ANALYSIS_AMENDMENT.md`; it is not presented as preregistered. Edge rule proxies were reconstructed after review, so their difference correction is only a descriptive reference.\n\nIntervals use 5,000 stratified question-level percentile-bootstrap replicates and seed 20261013, resampling within dataset-by-question-stratum cells while retaining every condition and r1/r2 pair of a question. They are **95% between-question descriptive bootstrap intervals with fixed audit weights**. Audit samples are not resampled; these are not full two-stage design confidence intervals and exclude unknown annotation bias. MuSiQue 4hop/2 has one question, so its between-question variation cannot be estimated. No confirmatory p-values, Holm results or significance claims are provided.\n\n## 3. Overall node distributions\n")
parts.append(table(['disposition', 'Original exact 769', 'Reviewed sample 633', 'Remaining 6329 estimate', 'Total 7098 estimate', 'Percentage of 7098'], [[n, num(val('node', 'prior_exact', 'disposition_' + n)), num(val('node', 'sample_observed', 'disposition_' + n)), num(val('node', 'remaining_estimated', 'disposition_' + n)), num(val('node', 'audit_HT', 'disposition_' + n)), pct(float(val('node', 'audit_HT', 'disposition_' + n)) / 7098)] for n in ['decided', 'missing', 'semantic_negative']]))
parts.append('The following is the weighted distribution over all message-node scopes, not a question macro or terminal CSR. Pooling models/protocols serves only to inventory the frozen panel, not estimate a population model effect.\n')
parts.append(table(['Message-node metric', 'HT estimated count', 'HT %', 'Original exact + candidate %', 'Difference-adjusted %'], [[n, num(val('node', 'audit_HT', n)), pct(float(val('node', 'audit_HT', n)) / 7098), pct(float(val('node', 'candidate_baseline', n)) / 7098), pct(float(val('node', 'audit_difference', n)) / 7098)] for n in ['CSR', 'ESS', 'VSSR', 'AA']]))
parts.append(table(['Support outcome', 'HT estimated count', 'Percentage of 7098'], [[n, num(val('node', 'audit_HT', 'outcome_' + n)), pct(float(val('node', 'audit_HT', 'outcome_' + n)) / 7098)] for n in ['FullSupport', 'PartialSupport', 'NotSupport', 'SourceMissing', 'ClaimDropped']]))
parts.append('In this cross-sectional table, ClaimDropped includes absent, partial and uninterpretable outcomes, meaning the node does not fully express the equivalent claim. It cannot directly be called propagation-caused claim loss. Source identity differs from support: ESS can hold with insufficient support, while valid substitution does not count as ESS.\n\n## 4. Message-node results for primary DeepSeek conditions\n\nThese are all-message-node question-macro percentage estimates. Each question contributes one two-repeat mean per condition, while its internal metric retains the node-by-truth-scope process denominator. Both initial-read and communication layers are included. Under division of labor, a node failing to express facts held by other nodes does not imply terminal information loss.\n')
parts.append(table(['Condition', 'Questions', 'CSR HT', 'ESS HT', 'VSSR HT', 'AA HT'], [[label(c['cell_id']), c['question_n']] + [pct(stat(c['cell_id'], n)['question_macro_mean']) for n in ['CSR', 'ESS', 'VSSR', 'AA']] for c in maincells]))
parts.append('Candidate-assisted difference-adjustment sensitivity results follow, as percentages [95% descriptive interval]. Both direct HT and adjusted views remain available. Full candidate baselines, sampled-item replacement views and communication-layer results are in the supplementary outputs.\n')
parts.append(table(['Condition', 'CSR adjusted', 'ESS adjusted', 'VSSR adjusted', 'AA adjusted'], [[label(c['cell_id'])] + [ci(stat(c['cell_id'], n, 'audit_difference')) for n in ['CSR', 'ESS', 'VSSR', 'AA']] for c in maincells]))
parts.append('For example, adjusted 2Wiki B0 CSR of 100% [100%,100%] only means that the candidate-assisted view has no between-question variation for these questions and observed audit discrepancies. It does not establish correctness of all unreviewed records. The same applies to 0% [0%,0%] and zero-width contrast intervals: they establish neither perfect reliability, no difference nor equivalence.\n')
parts.append('## 5. Paired condition contrasts\n\nDifferences are M minus comparator in percentage points; n counts paired questions after averaging r1/r2. HT/adjusted differences reflect sparse audit coverage and candidate assistance. Selective choice of estimation view cannot establish robustness.\n')
pick = [r for r in D if r['role'] == 'primary_descriptive' and r['kind'] == 'node' and (r['question_stratum'] == 'ALL') and (r['view'] == 'audit_HT')]
di = {(r['dataset'], r['kind'], r['comparison'], r['metric'], r['view'], r['question_stratum']): r for r in D if r['status'] == 'computed'}
paired = []
for r in pick:
    k = (r['dataset'], r['kind'], r['comparison'], r['metric'])
    a = di[*k, 'audit_difference', 'ALL']
    b = di[*k, 'candidate_baseline', 'ALL']
    paired.append([r['dataset'], r['comparison'], r['metric'], r['question_n'], ci(r, 'difference'), ci(a, 'difference'), pct(b['difference'])])
parts.append(table(['Dataset', 'Contrast', 'Metric', 'n questions', 'HT difference [interval]', 'Difference-adjusted contrast [interval]', 'Candidate-baseline contrast'], paired))
parts.append('M–B0 message-node differences cannot be written as communication reducing terminal system performance: B0 has one centralized node per question, whereas M has five initial-read/communication nodes per observation, with different node-coverage denominators. M–B1 likewise needs union analysis to answer terminal-set retention. M–A1/A2 have more similar node composition but still require edge and subsequent terminal-union context and remain associations within this frozen sample.\n\nIn the 2Wiki difference-adjusted view, M–A1 contrasts are 0.13 points for CSR, 9.94 for ESS and 10.13 for AA; direct HT contrasts are −4.97, 6.97 and 5.99 with wider intervals. One may describe different condition contrasts for source identity/support and claim expression in the candidate-assisted results, but not infer confirmatory causation. Small candidate-assisted M–A2 contrasts do not demonstrate equivalence. MuSiQue adjusted M–B1 CSR is −0.40 and ESS −2.01 points; both intervals cross zero, precluding claims of stable improvement or degradation.\n\n## 6. Overall edge distributions and applicable events\n')
parts.append(table(['disposition', 'Original exact 559', 'Reviewed sample 189', 'Remaining 1885 estimate', 'Total 2444 estimate', '% of 2444'], [[n, num(val('edge', 'prior_exact', 'disposition_' + n)), num(val('edge', 'sample_observed', 'disposition_' + n)), num(val('edge', 'remaining_estimated', 'disposition_' + n)), num(val('edge', 'audit_HT', 'disposition_' + n)), pct(float(val('edge', 'audit_HT', 'disposition_' + n)) / 2444)] for n in ['not_applicable', 'decided', 'semantic_negative']]))
edge_metrics = [('EdgeClaimRetention', 'ClaimRetained', 'ClaimApplicable'), ('EdgeExactSourceRetention', 'SourceExactApplicable', 'ExactApplicable'), ('EdgeValidSubstitution', 'SubstitutionValid', 'SubstitutionApplicable')]
parts.append(table(['Metric', 'HT numerator', 'HT applicable denominator', 'Percentage within applicable denominator'], [[n, num(val('edge', 'audit_HT', a)), num(val('edge', 'audit_HT', b)), pct(float(val('edge', 'audit_HT', a)) / float(val('edge', 'audit_HT', b))) if float(val('edge', 'audit_HT', b)) else 'NA'] for n, a, b in edge_metrics]))
parts.append("Exact source retention on an edge refers to parent–child event status, not canonical ESS or sufficient support. The 100% valid-substitution rate comes from **one applicable event**, so it cannot establish generally reliable substitution. Absence of sampled missing/needs_review outcomes does not prove absence among unreviewed edges.\n\nSeventeen original formal Qwen edges have claim_event=claim_dropped together with source_set_retained_exact (five chain, twelve star). Labels and event frequencies are preserved, but these records lie outside ExactSourceRetention's domain and enter neither numerator nor denominator. An unconditional numerator from the older calculation function would yield condition rates above 100%. This report corrects the count/domain alignment with traceable excluded counts, without rewriting human adjudication.\n")
edgecells = [c for c in maincells + auxcells if c['edge_scope_n'] != '0']
parts.append(table(['Condition', 'Questions/observations/scopes', 'ClaimRetention % (denominator)', 'ExactSourceRetention % (denominator)', 'ValidSubstitution % (denominator)'], [[label(c['cell_id']), f"{c['question_n']}/{c['observation_n']}/{c['edge_scope_n']}"] + [f"{pct(stat(c['cell_id'], n, kind='edge').get('applicable_rate'))} ({num(stat(c['cell_id'], n, kind='edge').get('applicable_denominator_estimate'))})" for n, _, _ in edge_metrics] for c in edgecells]))
parts.append('B0/B1 have no communication edges, so every edge-condition metric is NA, never zero. Question-paired M–A1/A2 event-frequency contrasts are in `paired_condition_differences.csv`; they use all edge scopes within each question, unlike the applicable-event denominators above. Full claim/source/support event distributions are in supplementary tables.\n\n## 7. Node-candidate usability\n')
parts.append(table(['Comparison field', 'Agreement/633', 'Sample agreement %', 'Stratified weighted agreement %'], [[r['field'], f"{r['equal_n']}/633", pct(r['sample_agreement']), pct(r['weighted_agreement'])] for r in rows('node_candidate_agreement.csv')]))
parts.append('Comparisons normalize JSON booleans to M2 string enums. The six records with at least one discrepancy are 292, 571, 585, 619, 621 and 627. Record 292 changes only support_fine; the other five change disposition. Source localization/support for 571/619/621, valid alternative sources for 627 and the missing target predicate for 585 follow final review, not outdated table values. Itemwise discrepancies, reasons and confusion matrices are provided separately.\n\n**Usability conclusion: original node candidates support clearly labeled descriptive statistics and sensitivity analysis, and can serve as auxiliary variables for human-sample-corrected estimation. They do not justify promoting all candidates to itemwise human semantic truth.** This judgment rests on empirical stratified-sample agreement within the remaining 6,329 records and comparisons between population metrics and candidate views. It implies neither a 99% correctness probability for each unsampled candidate nor equal accuracy for rare fields, small condition contrasts or cross-node union.\n\nThe 769 original reviews include risk-directed selection and are excluded from the 633-item agreement denominator. Agreement on seven primary fields is not accuracy on all M2 fields, qualification or union. The audit is not independent double-blind relabeling of every item; candidate exposure and common-method bias may occur and should be disclosed.\n')
maxdiff = max((abs(float(val('node', 'audit_HT', n)) - float(val('node', 'candidate_baseline', n))) / 7098 * 100 for n in ['CSR', 'ESS', 'VSSR', 'AA']))
parts.append(f'Across all node-scope CSR/ESS/VSSR/AA estimates, the largest difference between direct HT and the original-exact-plus-original-candidate view is **{maxdiff:.2f} percentage points**. This supports similarity of overall distributions, not stability in every question stratum or condition contrast. Direct HT varies substantially in sparse strata; consult complete supplementary tables for grouped comparisons.\n\n')
parts.append('Edge-candidate evidence is separate: only three sampled records had genuine original candidates, with 3/3 agreement on four fields. The other 186 were post-review reconstructions using original node candidates and frozen rules: disposition agreement is 185/186 and four-field agreement 182/186. All 139 structurally clear inapplicable cases agree, whereas the harder E1 retained-endpoint stratum has four-field agreement of only 43/47 (91.49%). High node agreement cannot automatically raise confidence in edges or union.\n\n## 8. Worst-case ranges and auxiliary models\n\nThe following ranges make no assumption that unreviewed candidates are valid. Assigning every unreviewed record metric values of 0 or 1 yields conservative identification bounds constrained by reviewed evidence, not 95% intervals or predictions. There are 5,696 unreviewed nodes and 1,696 unreviewed edges. With no additional missing/needs_review items to assign, their positive/negative sensitivity cases coincide, while unreviewed-candidate error remains possible.\n')
parts.append(table(['Scope', 'Metric', 'Reviewed scopes', 'Unreviewed scopes', 'Conservative lower bound %', 'Conservative upper bound %'], [[r['kind'], r['metric'], r['individually_reviewed_n'], r['unreviewed_n'], pct(r['worst_case_lower']), pct(r['worst_case_upper'])] for r in rows('unreviewed_worst_case_bounds.csv')]))
parts.append('Auxiliary models use the same 40 questions only. Qwen chain is paired with DeepSeek 1.0.1c-r2 chain; Qwen star is listed separately. Differences in model, service, prompt and execution cannot be interpreted as causal model-size or topology effects.\n')
parts.append(table(['Auxiliary condition', 'CSR HT', 'ESS HT', 'AA HT', 'CSR difference-adjusted', 'ESS difference-adjusted', 'AA difference-adjusted'], [[label(c['cell_id'])] + [pct(stat(c['cell_id'], n, v)['question_macro_mean']) for v in ['audit_HT', 'audit_difference'] for n in ['CSR', 'ESS', 'AA']] for c in auxcells]))
parts.append('## 9. Results wording for the paper\n')
parts.append(f"In the 60-question exploratory semantic panel fixed in advance, 680 original-protocol observations cover 7,098 message-node–truth-claim scopes and 2,444 dependency-edge–truth-claim scopes. The node population combines 769 existing formal human judgments with stratified human-sample estimation for the remaining 6,329 records. Among 633 sampled nodes, candidate/human disposition agrees for 628/633 (99.21%), and all seven primary fields agree for 627/633 (99.05%); weighted agreements are 99.20% and 99.04%, respectively. These results support labeled sensitivity analysis and sample-based correction using candidates, without granting itemwise human-final status to unreviewed records.\n\nAt the all-message-node scope level, direct human-audit-weighted complete semantic survival is {pct(float(val('node', 'audit_HT', 'CSR')) / 7098)}%, exact canonical-source-set retention is {pct(float(val('node', 'audit_HT', 'ESS')) / 7098)}%, valid source substitution is {pct(float(val('node', 'audit_HT', 'VSSR')) / 7098)}%, and simultaneous complete semantics and sufficient current support is {pct(float(val('node', 'audit_HT', 'AA')) / 7098)}%. These metrics separately measure expression, source identity, and current support, not terminal system performance. In edge estimates, 73.24% of scopes have no applicable propagation event and are not semantic errors. Report applicable-denominator retention separately from event frequency over all scopes.\n\nCondition results aggregate by question, averaging DeepSeek r1/r2 before paired differences. Sparse human audits within questions and rare events produce substantial variation in direct weighted estimates and fixed-weight between-question descriptive intervals; complete-candidate and human-sample difference-adjusted sensitivity views are also reported. Interpretations are limited to this frozen exploratory panel; repair, supplemental and full-M3 confirmatory effects were not tested. **Historical status as of 2026-10-13:** terminal union had not been established, so this report does not conclude on terminal CSR/ESS contrasts. See the version notice above for the completed 2026-10-15 union analysis.\n\n## 10. Verification and delivery boundaries\n\n- All frozen-manifest hashes matched; original node/edge validators passed; existing overall distributions and candidate agreements were independently recomputed.\n- M2 payload checks passed for 7098 node candidates, 769 original formal node judgments, 633 human-review analysis conversions, 1885 edge candidates, 559 original formal edge judgments and 189 sampled edge reviews. Original candidate-envelope batch/source-hash metadata remains available; audit provenance was not removed.\n- Original inputs, candidates, human forms, approval identities and frozen sampling were unchanged. Statistical scripts, denominator ledgers, question-level tables, table SHA-256 values and version information are stored alongside this report.\n- Complete four-stratum 2Wiki, six-stratum MuSiQue and hop-group results are in `SUPPLEMENTARY_TABLES.md` and CSVs. Degenerate single-question bootstrap intervals do not prove high precision.\n- Completed node/edge review need not be repeated. **Historical next step at this report's date:** retaining the original terminal research question required terminal-union semantic judgments and quality review, as described separately. That work was subsequently completed on 2026-10-15.\n\nFile index: `panel_cells.csv` identifies the panel; `denominator_ledger.csv` records actual denominators and estimated represented totals; `observation_metrics.csv` and `question_metrics.csv` are analysis base tables; `condition_and_stratum_tables.csv` and `paired_condition_differences.csv` contain full paper statistics; `node_candidate_agreement.csv`, `node_candidate_disagreements.csv` and `node_candidate_confusion.csv` cover candidate audits; `scope_global_metrics.csv` contains totals and event frequencies; `unreviewed_worst_case_bounds.csv` contains conservative bounds; the two `*_analysis_ledger.jsonl` files record identities and judgment provenance; `verification.json`, `m2_validation.json` and `manifest.json` provide checks and hashes.\n")
(P / 'NODE_EDGE_PAPER_STATISTICS_REPORT.md').write_text('\n\n'.join(parts), encoding='utf-8')
sup = ['# Complete stratified supplementary tables for nodes and edges', 'All percentages use %. HT denotes direct audit expansion; difference correction is candidate-assisted sensitivity estimation. Intervals are descriptive between-question bootstrap intervals with fixed audit weights, especially unstable in small and single-question strata. See the main report for interpretation and metric definitions.']
for view in ['audit_HT', 'audit_difference', 'candidate_baseline', 'candidate_sample_corrected']:
    sup.append('## Node ' + view)
    data = []
    for c in maincells + auxcells:
        cell = c['cell_id']
        strata = sorted({r['question_stratum'] for r in S if r['cell_id'] == cell and r['question_stratum'] != 'ALL'})
        for st in ['ALL'] + strata:
            rr = stat(cell, 'CSR', view, st=st)
            data.append([label(cell), st, rr['question_n'], rr['observation_n'], rr['scope_n'], num(rr['represented_scope_weight'])] + [ci(stat(cell, n, view, st=st)) for n in ['CSR', 'ESS', 'VSSR', 'AA']])
    sup.append(table(['Condition', 'Question stratum', 'Questions', 'obs', 'scope', 'Weighted represented count', 'CSR [interval]', 'ESS [interval]', 'VSSR [interval]', 'AA [interval]'], data))
sup.append('## Node primary and difference-corrected estimates by communication layer')
for view in ['audit_HT', 'audit_difference']:
    data = []
    for c in maincells + auxcells:
        cell = c['cell_id']
        phases = sorted({r['phase'] for r in S if r['cell_id'] == cell and r['phase'] != 'all'})
        for phase in phases:
            if ('node', view, cell, phase, 'ALL', 'CSR') not in IDX:
                continue
            rr = stat(cell, 'CSR', view, phase=phase)
            data.append([label(cell), phase, rr['question_n'], rr['scope_n']] + [ci(stat(cell, n, view, phase=phase)) for n in ['CSR', 'ESS', 'VSSR', 'AA']])
    sup.append('### ' + view)
    sup.append(table(['Condition', 'Communication layer', 'Questions', 'scope', 'CSR', 'ESS', 'VSSR', 'AA'], data))
sup.append('## Edge applicable-event rates by stratum')
data = []
for c in edgecells:
    cell = c['cell_id']
    strata = sorted({r['question_stratum'] for r in S if r['cell_id'] == cell and r['question_stratum'] != 'ALL'})
    for st in ['ALL'] + strata:
        rr = stat(cell, 'EdgeClaimRetention', kind='edge', st=st)
        data.append([label(cell), st, rr['question_n'], rr['observation_n'], rr['scope_n'], num(rr['represented_scope_weight'])] + [f"{pct(stat(cell, n, kind='edge', st=st)['applicable_rate'])} / {num(stat(cell, n, kind='edge', st=st)['applicable_denominator_estimate'])}" for n, _, _ in edge_metrics])
sup.append(table(['Condition', 'Question stratum', 'Questions', 'obs', 'scope', 'Weighted represented count', 'Claim %/denominator', 'Exact %/denominator', 'Substitution %/denominator'], data))
sup.append('## Edge overall event distributions')
sup.append(table(['Event', 'HT estimated count', '% of 2444'], [[r['metric'], num(r['estimated_count']), pct(r['scope_rate'])] for r in G if r['kind'] == 'edge' and r['view'] == 'audit_HT' and r['metric'].startswith(('claim_event_', 'source_event_', 'support_event_'))]))
sup.append('## Edge primary-condition paired frequency differences')
sup.append('The denominator is all within-question edge scopes, not the applicable-event denominators above. B0/B1 are not applicable.')
sup.append(table(['Dataset', 'Contrast', 'View', 'Metric', 'Questions', 'Difference in percentage points [interval]'], [[r['dataset'], r['comparison'], r['view'], r['metric'], r['question_n'], ci(r, 'difference')] for r in D if r['role'] == 'primary_descriptive' and r['kind'] == 'edge' and (r['question_stratum'] == 'ALL') and (r['status'] == 'computed')]))
sup.append('## Auxiliary-model paired differences')
sup.append(table(['Contrast', 'Scope', 'View', 'Metric', 'Questions', 'Difference in percentage points [interval]'], [[r['comparison'], r['kind'], r['view'], r['metric'], r['question_n'], ci(r, 'difference')] for r in D if r['role'] == 'model_protocol_descriptive' and r['question_stratum'] == 'ALL' and (r['status'] == 'computed')]))
(P / 'SUPPLEMENTARY_TABLES.md').write_text('\n\n'.join(sup), encoding='utf-8')

def sha(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()
m = json.loads((P / 'manifest.json').read_text(encoding='utf-8'))
m['input_sha256'][str(Path(__file__).resolve())] = sha(Path(__file__).resolve())
m['input_sha256'][str(P / 'ANALYSIS_AMENDMENT.md')] = sha(P / 'ANALYSIS_AMENDMENT.md')
m['output_sha256'] = {p.name: sha(p) for p in sorted(P.iterdir()) if p.is_file() and p.name != 'manifest.json'}
(P / 'manifest.json').write_text(json.dumps(m, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print('Rendered main report and supplementary tables; refreshed manifest.')
